import{_ as i,o as a,c as t,ag as n}from"./chunks/framework.HcBc_Mb9.js";const p=JSON.parse('{"title":"Discernment","description":"","frontmatter":{},"headers":[],"relativePath":"ai-fluency/04-discernment.md","filePath":"ai-fluency/04-discernment.md"}'),r={name:"ai-fluency/04-discernment.md"};function o(l,e,s,c,d,u){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="discernment" tabindex="-1">Discernment <a class="header-anchor" href="#discernment" aria-label="Permalink to &quot;Discernment&quot;">​</a></h1><h2 id="what-you-ll-learn" tabindex="-1">What you&#39;ll learn <a class="header-anchor" href="#what-you-ll-learn" aria-label="Permalink to &quot;What you&#39;ll learn&quot;">​</a></h2><ul><li>Understand how to evaluate AI outputs and processes thoughtfully</li><li>Develop critical thinking skills for your AI interactions</li><li>Learn to identify and address quality concerns in your AI interactions</li></ul><h2 id="key-takeaways" tabindex="-1">Key Takeaways <a class="header-anchor" href="#key-takeaways" aria-label="Permalink to &quot;Key Takeaways&quot;">​</a></h2><ul><li>Discernment is your ability to thoughtfully evaluate what AI produces, how it produces it, and how it behaves.</li><li>Product Discernment focuses on evaluating the quality of actual outputs (accuracy, appropriateness, coherence, relevance).</li><li>Process Discernment involves assessing how the AI arrived at its output, looking for logical errors, attention gaps, or inappropriate reasoning.</li><li>Performance Discernment evaluates how the AI behaves within the collaboration process itself, considering whether its communication style is effective for your needs.</li><li>Discernment works hand-in-hand with Description in a continuous feedback loop.</li><li>Even the most advanced AI systems benefit from human judgment and oversight.</li></ul><h2 id="you-need" tabindex="-1">You Need <a class="header-anchor" href="#you-need" aria-label="Permalink to &quot;You Need&quot;">​</a></h2><p>Your ability to critically evaluate what AI produces, how it produces it and how it behaves</p><ul><li><strong>Domain expertise</strong></li><li><strong>An understanding of how AI systems work and their typical shortcomings</strong></li></ul><h2 id="product-discernment" tabindex="-1">Product Discernment <a class="header-anchor" href="#product-discernment" aria-label="Permalink to &quot;Product Discernment&quot;">​</a></h2><p>Your capacity to judge the quality of the AI output</p><ul><li>Factually accurate?</li><li>Appropriate to auidence and purpose?</li><li>Coherent and well-structured?</li><li>Does it meet my requirements?</li><li>Does it add value?</li></ul><h2 id="process-discernment" tabindex="-1">Process Discernment <a class="header-anchor" href="#process-discernment" aria-label="Permalink to &quot;Process Discernment&quot;">​</a></h2><p>Your capacity to judge the quality of the problem solving approach</p><ul><li>logical inconsistency</li><li>Lapses in attention</li><li>Inappropriate steps</li><li>Getting stuck on one small detail</li><li>Getting trapped in circular reasoning</li></ul><h2 id="performance-discernment" tabindex="-1">Performance Discernment <a class="header-anchor" href="#performance-discernment" aria-label="Permalink to &quot;Performance Discernment&quot;">​</a></h2><p>Your capacity to judge AI behaviors</p><ul><li>Is the communication style appropriate?</li><li>Is the information at the right level?</li><li>Is the response to feedback appropriate?</li><li>Is the interation efficent?</li></ul><h2 id="effective-feedback" tabindex="-1">Effective Feedback <a class="header-anchor" href="#effective-feedback" aria-label="Permalink to &quot;Effective Feedback&quot;">​</a></h2><ul><li>Specifying the problem</li><li>Clearly explaining why it is a problem</li><li>Providing concrete suggestions for improvement</li><li>Revising your instructions or examples</li></ul><h2 id="downloads" tabindex="-1">Downloads <a class="header-anchor" href="#downloads" aria-label="Permalink to &quot;Downloads&quot;">​</a></h2><div style="border-radius:18px;background:#d2cfe3;padding:28px;display:flex;gap:24px;align-items:center;"><div style="flex:0 0 140px;text-align:center;"><div style="width:120px;height:120px;margin:0 auto;border-radius:18px;background:#f5f3f7;display:flex;align-items:center;justify-content:center;"><span style="font-size:64px;line-height:1;color:#2d2a32;">✍️</span></div></div><div style="flex:1;"><h3 style="margin:0 0 10px 0;font-size:28px;color:#2d2a32;">Discernment Summary</h3><p style="margin:0 0 18px 0;font-size:18px;color:#2d2a32;line-height:1.6;"> Quick reference for the Discernment competency. </p><a href="/anthropic-notes/ai-fluency/1.6_Discernment_Summary_16x9.pdf" style="display:inline-block;padding:12px 22px;border-radius:12px;background:#6f6a80;color:#ffffff;text-decoration:none;font-weight:600;">Download</a></div></div>',21)])])}const m=i(r,[["render",o]]);export{p as __pageData,m as default};
